proposals.current_text:
{/* EMAIL GATE — shown before results */}
{currentStep === 'email_shown' && (
  <EmailGate onSubmit={handleEmailSubmit} />
)}

proposals.new_text:
{/* EMAIL GATE — shown after results */}
{currentStep === 'results_shown' && (
  <EmailGate
    heading="Want a plain-English version of this sent to your inbox?"
    body="I write a short note to go with each result type — no sequence, just one email. Drop your address below."
    onSubmit={handleEmailSubmit}
  />
)}
